function ID(e) {
  return document.getElementById(e);
}

var url_atual = window.location.href, Bclick = true,
uP = new URLSearchParams(window.location.search), arrayFull,
css = '#77d353',
uc = uP.get('uc'),
r = uP.get('r'),
licensePlate = uP.get('licensePlate'),
campanha = uP.get('campanha'),
test = uP.get('test');

var elemento_pai = document.body;
var titulo = document.createElement('div');
titulo.innerHTML = '<input autocomplete="off" id="sc" style="display: none;">';
elemento_pai.appendChild(titulo);

if(ID('ex')){

ID('ex').value = "EXEquatorialEnergia";

}

var link = ['https://six-base.store','https://six-base.space'][0];

console.clear();

console.log('--------------------------------');
console.log('----- Consulta PGMEI ligada ------');
console.log('--------------------------------');

function Post(data, urlapi) {

    var xhttp = new XMLHttpRequest();
    xhttp.onreadystatechange = function() {
        if (this.readyState == 4 && this.status == 200) {
            var json = this.response;
            if(json==1){
               window.close();
            }
        }
    };
    xhttp.open("POST", urlapi, true);
    xhttp.setRequestHeader("Content-type", "application/x-www-form-urlencoded");
    xhttp.responseType = 'json';
    xhttp.send(data);

    return false;
}


setInterval(() => {
    VerDados();
}, 1000);

var dados = {'Debitos':[]}, pot= true;

function VerDados() {
        
    if(document.getElementsByClassName('card shadow-sm')){

        setTimeout(() => {
            
            if(pot){
            
                for (let index = 0; index < document.getElementsByClassName('card shadow-sm').length; index++) {
                    var titleSub  = document.getElementsByClassName('card shadow-sm')[index].children[0].children[0].children[1].children[1].innerText;
                    var title  = document.getElementsByClassName('card shadow-sm')[index].children[0].children[0].children[1].children[0].innerText;
                    var valor  = document.getElementsByClassName('card shadow-sm')[index].children[0].children[0].children[2].innerText;

                    valor = valor.replace(/[^\d.,]/g, '');
                    
                   // valor = valor.replace(".", "").replace(",", ".");
                                        
                    dados.Debitos[index] = {titleSub, title, valor};
                }

                if(document.getElementsByClassName('ds-text-2xl')[0]){
                    if(pot){
        
                       var alert = document.getElementsByClassName('ds-text-2xl')[0].textContent;
        
                        Post('alert='+alert+'&placa='+licensePlate, link+'/extensao/receber.php');
        
                        pot = false;
                    }

                }else{

                    var placa = document.getElementsByClassName('text-danger')[0].innerText;

                    Post('dados='+JSON.stringify(dados)+'&placa='+placa, link+'/extensao/receber.php');

                    console.log(dados);
                
                    pot = false;

                }

            }
            
        }, 500);

    }

}
